import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ----------------------------------------------------------------------
# C++ source for the custom LeakyReLU CUDA kernel and wrapper function
# ----------------------------------------------------------------------
cpp_sources = """\
#include <torch/extension.h>
#include <cuda_runtime.h>

torch::Tensor leaky_relu_cuda(torch::Tensor x, float negative_slope);
"""

cuda_sources = """\
__global__ void leaky_relu_kernel(const float* input, float* output, int size, float negative_slope) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx];
        if (val >= 0.0f) {
            output[idx] = val;
        } else {
            output[idx] = negative_slope * val;
        }
    }
}

torch::Tensor leaky_relu_cuda(torch::Tensor x, float negative_slope) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    leaky_relu_kernel<<<num_blocks, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        size,
        negative_slope
    );

    return out;
}
"""

element_leaky_relu = load_inline(
    name="leaky_relu",
    cpp_sources=cpp_sources,
    cuda_sources=cuda_sources,
    functions=["leaky_relu_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self, negative_slope: float = 0.01):
        super().__init__()
        self.negative_slope = negative_slope
        self.leaky_relu_cuda = element_leaky_relu

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.leaky_relu_cuda(x, self.negative_slope)
